:root {
  --bg: #0a0a0d;
  --bg-elevated: #14141a;
  --bg-card: #18181f;
  --bg-card-hover: #1f1f28;
  --border: #26262f;
  --border-strong: #3a3a45;
  --text: #f5f5f7;
  --text-muted: #9a9aa8;
  --text-dim: #6b6b78;
  --accent: #d4ff3a;
  --accent-hover: #e3ff5e;
