* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
img { display: block; max-width: 100%; }

.container {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 28px;
}

/* ============ ANNOUNCEMENT BAR ============ */
.announce {
  background: linear-gradient(90deg, #1a1f08, #0a0a0d 40%, #1a1f08);
  border-bottom: 1px solid var(--border);
  font-size: 13px;
  color: var(--text-muted);
  overflow: hidden;
  height: 38px;
  display: flex;
  align-items: center;
}
.announce-track {
  display: flex;
  gap: 60px;
  white-space: nowrap;
  animation: scroll-x 32s linear infinite;
  padding-left: 28px;
}
.announce-item { display: inline-flex; align-items: center; gap: 10px; }
.announce-item .dot { width: 4px; height: 4px; border-radius: 50%; background: var(--accent); }
.announce-item strong { color: var(--text); font-weight: 600; }
@keyframes scroll-x {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ============ NAV ============ */
.nav {
  position: sticky;
  top: 0;
