  height: 380px;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 200'><defs><linearGradient id='g' x1='0' y1='0' x2='1' y2='1'><stop offset='0' stop-color='%23d4ff3a'/><stop offset='1' stop-color='%2395b81d'/></linearGradient></defs><circle cx='100' cy='100' r='60' fill='none' stroke='url(%23g)' stroke-width='1' opacity='0.4'/><circle cx='100' cy='100' r='80' fill='none' stroke='url(%23g)' stroke-width='1' opacity='0.25'/><circle cx='100' cy='100' r='100' fill='none' stroke='url(%23g)' stroke-width='1' opacity='0.12'/><path d='M60 130 Q100 60 140 130 Q100 110 60 130' fill='url(%23g)' opacity='0.85'/><circle cx='100' cy='90' r='30' fill='%230a0a0d'/></svg>") center/contain no-repeat;
  pointer-events: none;
  opacity: 0.85;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(212, 255, 58, 0.12);
  color: var(--accent);
  padding: 6px 12px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  width: fit-content;
  border: 1px solid rgba(212, 255, 58, 0.2);
}
.hero-eyebrow .pulse {
  width: 6px; height: 6px; background: var(--accent); border-radius: 50%;
  animation: pulse 1.6s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; box-shadow: 0 0 0 0 rgba(212, 255, 58, 0.6); }
  50% { opacity: 0.6; box-shadow: 0 0 0 6px rgba(212, 255, 58, 0); }
}
.hero h1 {
  font-family: 'Space Grotesk', sans-serif;
  font-size: clamp(44px, 5.5vw, 76px);
  font-weight: 700;
  line-height: 0.98;
  letter-spacing: -0.03em;
  margin: 24px 0 20px;
  max-width: 14ch;
