}
.hero h1 em { font-style: normal; color: var(--accent); }
.hero p {
  color: var(--text-muted);
  font-size: 17px;
  max-width: 44ch;
  margin-bottom: 36px;
  position: relative;
  z-index: 1;
}
.hero-cta { display: flex; gap: 12px; position: relative; z-index: 1; }
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 24px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 600;
  transition: transform 0.15s, background 0.15s, color 0.15s;
}
.btn-primary {
  background: var(--accent);
