  border: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 250px;
  transition: transform 0.2s, border-color 0.2s;
  cursor: pointer;
}
.hero-card:hover { transform: translateY(-3px); border-color: var(--border-strong); }
.hero-card-1 { background: linear-gradient(140deg, #2a1248, #14141a 70%); }
.hero-card-1::before {
  content: '';
  position: absolute;
  right: -30px;
  top: -30px;
  width: 220px;
  height: 220px;
  background: radial-gradient(circle, rgba(190, 100, 255, 0.4), transparent 70%);
}
.hero-card-2 { background: linear-gradient(140deg, #06303a, #14141a 70%); }
.hero-card-2::before {
  content: '';
  position: absolute;
  right: -30px;
  top: -30px;
  width: 220px;
  height: 220px;
  background: radial-gradient(circle, rgba(80, 200, 240, 0.35), transparent 70%);
}
.hero-card-tag {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
