  font-weight: 500;
  border-radius: 999px;
  color: var(--text-muted);
  transition: color 0.15s, background 0.15s;
}
.tab:hover { color: var(--text); }
.tab.active { background: var(--text); color: #000; }
.see-all {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-muted);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 16px;
  border-radius: 999px;
  border: 1px solid var(--border);
  transition: color 0.15s, border-color 0.15s;
}
.see-all:hover { color: var(--text); border-color: var(--border-strong); }

/* ============ PRODUCT GRID ============ */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.product {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform 0.2s, border-color 0.2s, background 0.2s;
  display: flex;
  flex-direction: column;
}
.product:hover { background: var(--bg-card-hover); border-color: var(--border-strong); transform: translateY(-3px); }
.product-media {
  aspect-ratio: 1;
  background: #1f1f28;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.product-media svg { width: 65%; height: 65%; transition: transform 0.3s; }
.product:hover .product-media svg { transform: scale(1.06) rotate(-2deg); }
.product-tag {
  position: absolute;
  top: 12px;
  left: 12px;
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(10px);
  color: var(--text);
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 999px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.product-tag.sale { background: var(--danger); color: #fff; }
.product-tag.new { background: var(--accent); color: #000; }
.wishlist {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(10px);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text);
  transition: color 0.15s, background 0.15s;
}
.wishlist:hover, .wishlist.on { color: var(--danger); }
.wishlist.on svg { fill: var(--danger); }
.product-body { padding: 18px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.product-cat { font-size: 11px; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.06em; font-weight: 500; }
.product-name {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: -0.01em;
}
.product-rating { display: flex; align-items: center; gap: 4px; font-size: 12px; color: var(--text-muted); }
.product-rating .stars { color: var(--gold); letter-spacing: 1px; }
.product-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 10px;
}
.price { display: flex; align-items: baseline; gap: 8px; }
.price .now { font-family: 'Space Grotesk', sans-serif; font-size: 18px; font-weight: 700; color: var(--text); }
.price .was { font-size: 13px; color: var(--text-dim); text-decoration: line-through; }
.add-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s, color 0.15s, transform 0.15s;
}
.add-btn:hover { background: var(--accent); color: #000; transform: rotate(90deg); border-color: var(--accent); }
.swatches { display: flex; gap: 4px; margin-top: 4px; }
.swatch { width: 14px; height: 14px; border-radius: 50%; border: 1px solid var(--border-strong); }

/* ============ DEALS ============ */
.deals-section {
  background:
    radial-gradient(ellipse at top, rgba(212, 255, 58, 0.04), transparent 50%),
    var(--bg);
}
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 20px;
  min-height: 540px;
}
.deal {
  border-radius: 20px;
  padding: 32px;
  position: relative;
  overflow: hidden;
  border: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  transition: transform 0.2s, border-color 0.2s;
}
.deal:hover { transform: translateY(-3px); border-color: var(--border-strong); }
.deal-1 {
  grid-column: 1;
  grid-row: 1 / span 2;
  background: linear-gradient(160deg, #ff4d6d22, #14141a 60%, #0a0a0d);
}
.deal-1::before {
  content: '';
  position: absolute;
  right: -60px;
  bottom: -60px;
  width: 360px;
  height: 360px;
  background: radial-gradient(circle, rgba(255, 77, 109, 0.25), transparent 65%);
}
.deal-2 { background: linear-gradient(140deg, #1a1f08, #0a0a0d); }
.deal-3 { background: linear-gradient(140deg, #1d1133, #0a0a0d); }
.deal-4 { background: linear-gradient(140deg, #14141a, #0a0a0d); border-color: var(--border-strong); }
.deal-5 { background: linear-gradient(140deg, #07232d, #0a0a0d); }

.deal-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 11px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  width: fit-content;
  position: relative;
  z-index: 1;
}
.deal-pill.hot { background: var(--danger); color: #fff; }
.deal-pill.new { background: var(--accent); color: #000; }
.deal-pill.flash { background: var(--gold); color: #000; }
.deal-pill.exclusive { background: rgba(255, 255, 255, 0.1); color: var(--text); border: 1px solid var(--border-strong); }

.deal h3 {
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  letter-spacing: -0.02em;
  position: relative;
  z-index: 1;
}
.deal-1 h3 { font-size: 44px; line-height: 1; margin-top: 16px; }
.deal-1 .big-num {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 120px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: -0.04em;
  background: linear-gradient(180deg, #ff4d6d, #ff8fa3);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  margin: 12px 0;
}
.deal h3:not(.deal-1 h3) { font-size: 22px; margin-top: 12px; }
.deal-2 h3, .deal-3 h3, .deal-4 h3, .deal-5 h3 { font-size: 22px; margin-top: 12px; line-height: 1.15; }
.deal p { color: var(--text-muted); font-size: 14px; margin-top: 8px; position: relative; z-index: 1; max-width: 32ch; }
.deal-foot { display: flex; align-items: center; gap: 12px; margin-top: 20px; position: relative; z-index: 1; }
.deal-link { font-size: 13px; font-weight: 600; color: var(--text); display: inline-flex; align-items: center; gap: 6px; }
.deal-link:hover { color: var(--accent); }

.countdown { display: flex; gap: 10px; margin-top: 20px; position: relative; z-index: 1; }
.cd-block {
  background: rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(10px);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 12px;
  text-align: center;
  min-width: 56px;
}
.cd-block strong {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 22px;
  font-weight: 700;
  color: var(--text);
  display: block;
  font-variant-numeric: tabular-nums;
}
.cd-block span { font-size: 10px; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.08em; }

/* ============ CATEGORIES ============ */
.cat-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}
.cat {
  aspect-ratio: 1;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  transition: background 0.15s, border-color 0.15s, transform 0.15s;
  cursor: pointer;
  padding: 16px;
}
.cat:hover { background: var(--bg-card-hover); border-color: var(--accent); transform: translateY(-3px); }
.cat-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  transition: background 0.15s;
}
.cat:hover .cat-icon { background: var(--accent-dark); }
.cat-name { font-size: 13px; font-weight: 600; }
.cat-count { font-size: 11px; color: var(--text-dim); }

/* ============ EDITORIAL ============ */
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 20px;
}
.article {
  border-radius: 20px;
  overflow: hidden;
  border: 1px solid var(--border);
  background: var(--bg-card);
  display: flex;
  flex-direction: column;
  transition: transform 0.2s, border-color 0.2s;
  cursor: pointer;
}
.article:hover { transform: translateY(-3px); border-color: var(--border-strong); }
.article-media {
  aspect-ratio: 16/10;
  position: relative;
  overflow: hidden;
}
.article-1 .article-media { aspect-ratio: 16/12; }
.article-media .gradient {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.85));
}
.article-1 .article-media { background: linear-gradient(135deg, #2c1845, #0a0a0d); }
.article-2 .article-media { background: linear-gradient(135deg, #073238, #0a0a0d); }
.article-3 .article-media { background: linear-gradient(135deg, #3a1a0a, #0a0a0d); }
.article-media::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 30% 70%, rgba(255,255,255,0.06), transparent 40%),
    radial-gradient(circle at 80% 20%, rgba(255,255,255,0.05), transparent 40%);
}
.article-1 .art-shape { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; }
.article-1 .art-shape svg { width: 60%; height: 60%; opacity: 0.7; }
.article-meta {
  position: absolute;
  top: 16px;
  left: 16px;
  display: flex;
  gap: 8px;
  z-index: 2;
}
.tag-chip {
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(10px);
  color: var(--text);
  font-size: 11px;
  font-weight: 600;
  padding: 5px 11px;
  border-radius: 999px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.article-body { padding: 22px; flex: 1; display: flex; flex-direction: column; gap: 8px; }
.article h3 {
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  letter-spacing: -0.01em;
  font-size: 20px;
  line-height: 1.2;
}
.article-1 h3 { font-size: 28px; }
.article-excerpt { color: var(--text-muted); font-size: 14px; }
.article-foot {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: auto;
  padding-top: 16px;
  font-size: 13px;
  color: var(--text-dim);
}
.avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #95b81d);
  color: #000;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
}
.article-foot .dot { width: 3px; height: 3px; background: var(--text-dim); border-radius: 50%; }

/* ============ NEWSLETTER ============ */
.newsletter {
  border-radius: 24px;
  padding: 64px;
  background:
    radial-gradient(ellipse at top right, rgba(212, 255, 58, 0.08), transparent 60%),
    radial-gradient(ellipse at bottom left, rgba(190, 100, 255, 0.06), transparent 60%),
    var(--bg-card);
  border: 1px solid var(--border);
  text-align: center;
  position: relative;
  overflow: hidden;
}
.newsletter::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
  background-size: 40px 40px;
  pointer-events: none;
}
.newsletter > * { position: relative; z-index: 1; }
.newsletter .eyebrow {
  display: inline-block;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 600;
  margin-bottom: 16px;
}
.newsletter h2 {
  font-family: 'Space Grotesk', sans-serif;
  font-size: clamp(32px, 4vw, 52px);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1;
  max-width: 18ch;
  margin: 0 auto 16px;
}
.newsletter p { color: var(--text-muted); max-width: 50ch; margin: 0 auto 32px; }
.newsletter-form {
  display: flex;
  gap: 8px;
  max-width: 460px;
  margin: 0 auto;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  padding: 6px;
}
.newsletter-form input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--text);
  padding: 0 18px;
  font-size: 14px;
  font-family: inherit;
}
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-form button {
  background: var(--accent);
  color: #000;
  padding: 12px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14px;
  transition: background 0.15s;
}
.newsletter-form button:hover { background: var(--accent-hover); }

/* ============ FOOTER ============ */
.footer {
  border-top: 1px solid var(--border);
  padding: 64px 0 32px;
  background: var(--bg-elevated);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}
.footer-brand p { color: var(--text-muted); font-size: 14px; margin-top: 16px; max-width: 28ch; }
.socials { display: flex; gap: 8px; margin-top: 20px; }
.social {
  width: 36px;
  height: 36px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: color 0.15s, background 0.15s, border-color 0.15s;
}
.social:hover { color: var(--accent); border-color: var(--accent); }
.footer h4 {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text);
  margin-bottom: 18px;
}
.footer ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer ul a { font-size: 14px; color: var(--text-muted); transition: color 0.15s; }
.footer ul a:hover { color: var(--text); }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--text-dim);
}
.footer-bottom .pay { display: flex; gap: 8px; }
.pay-card {
  width: 36px;
  height: 24px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  font-size: 9px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

/* ============ RESPONSIVE ============ */
@media (max-width: 1100px) {
  .hero-grid { grid-template-columns: 1fr; }
  .hero-side { grid-template-rows: auto; grid-template-columns: 1fr 1fr; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto; }
  .deal-1 { grid-column: 1 / -1; grid-row: auto; }
  .cat-grid { grid-template-columns: repeat(4, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 720px) {
  .container { padding: 0 18px; }
  .nav-links, .search { display: none; }
  .hero-main { padding: 36px 28px; min-height: auto; }
  .hero-main::after { display: none; }
  .hero-side { grid-template-columns: 1fr; }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr; }
  .newsletter { padding: 40px 24px; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 28px; }
  .footer-bottom { flex-direction: column; gap: 12px; }
  section { padding: 56px 0; }
  .hero-stats { gap: 24px; }
  .section-head { flex-direction: column; align-items: flex-start; }
}

data.permission_request:
PermissionRequest(kind=<PermissionRequestKind.WRITE: 'write'>, action=<PermissionRequestMemoryAction.STORE: 'store'>, args=None, can_offer_session_approval=True, citations=None, commands=None, diff='
diff --git a/workspace/sandbox/control/shopping-home-page--framework-react--style-dark/claude-opus-4.7__s3/styles.css b/workspace/sandbox/control/shopping-home-page--framework-react--style-dark/claude-opus-4.7__s3/styles.css
