@@ -1,0 +1,963 @@
+:root {
+  --bg: #0a0a0d;
+  --bg-elevated: #14141a;
+  --bg-card: #18181f;
+  --bg-card-hover: #1f1f28;
+  --border: #26262f;
+  --border-strong: #3a3a45;
+  --text: #f5f5f7;
+  --text-muted: #9a9aa8;
+  --text-dim: #6b6b78;
+  --accent: #d4ff3a;
+  --accent-hover: #e3ff5e;
+  --accent-dark: #1a1f08;
+  --danger: #ff4d6d;
+  --gold: #f5c451;
+  --radius: 14px;
+  --radius-sm: 8px;
+  --shadow: 0 10px 40px rgba(0, 0, 0, 0.4);
+}
+
+* { box-sizing: border-box; margin: 0; padding: 0; }
+
+html, body {
+  background: var(--bg);
+  color: var(--text);
+  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
+  -webkit-font-smoothing: antialiased;
+  line-height: 1.5;
+}
+
+a { color: inherit; text-decoration: none; }
+button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
+img { display: block; max-width: 100%; }
+
+.container {
+  max-width: 1320px;
+  margin: 0 auto;
+  padding: 0 28px;
+}
+
+/* ============ ANNOUNCEMENT BAR ============ */
+.announce {
+  background: linear-gradient(90deg, #1a1f08, #0a0a0d 40%, #1a1f08);
+  border-bottom: 1px solid var(--border);
+  font-size: 13px;
+  color: var(--text-muted);
+  overflow: hidden;
+  height: 38px;
+  display: flex;
+  align-items: center;
+}
+.announce-track {
+  display: flex;
+  gap: 60px;
+  white-space: nowrap;
+  animation: scroll-x 32s linear infinite;
+  padding-left: 28px;
+}
+.announce-item { display: inline-flex; align-items: center; gap: 10px; }
+.announce-item .dot { width: 4px; height: 4px; border-radius: 50%; background: var(--accent); }
+.announce-item strong { color: var(--text); font-weight: 600; }
+@keyframes scroll-x {
+  0% { transform: translateX(0); }
+  100% { transform: translateX(-50%); }
+}
+
+/* ============ NAV ============ */
+.nav {
+  position: sticky;
+  top: 0;
+  z-index: 100;
+  background: rgba(10, 10, 13, 0.85);
+  backdrop-filter: blur(20px);
+  -webkit-backdrop-filter: blur(20px);
+  border-bottom: 1px solid var(--border);
+}
+.nav-inner {
+  display: flex;
+  align-items: center;
+  gap: 40px;
+  height: 72px;
+}
+.logo {
+  font-family: 'Space Grotesk', sans-serif;
+  font-weight: 700;
+  font-size: 22px;
+  letter-spacing: -0.02em;
+  display: flex;
+  align-items: center;
+  gap: 8px;
+}
+.logo-mark {
+  width: 28px;
+  height: 28px;
+  background: var(--accent);
+  border-radius: 8px;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: #000;
+  font-size: 16px;
+  font-weight: 800;
+}
+.nav-links {
+  display: flex;
+  gap: 6px;
+  list-style: none;
+}
+.nav-links a {
+  padding: 8px 14px;
+  border-radius: var(--radius-sm);
+  font-size: 14px;
+  color: var(--text-muted);
+  font-weight: 500;
+  transition: color 0.15s, background 0.15s;
+}
+.nav-links a:hover { color: var(--text); background: var(--bg-elevated); }
+.nav-links a.active { color: var(--accent); }
+.search {
+  flex: 1;
+  max-width: 380px;
+  position: relative;
+}
+.search input {
+  width: 100%;
+  height: 40px;
+  background: var(--bg-elevated);
+  border: 1px solid var(--border);
+  color: var(--text);
+  border-radius: 999px;
+  padding: 0 16px 0 42px;
+  font-size: 14px;
+  outline: none;
