    { title: "Account", links: ["Sign In", "Create Account", "Wishlist", "Track Order", "Gift Cards"] },
  ];
  return (
    <footer className="footer">
      <div className="container">
        <div className="footer-grid">
          <div className="footer-brand">
            <a href="#" className="logo">
              <span className="logo-mark">N</span>
              <span>NORTHSTRIDE</span>
            </a>
            <p>Considered essentials for everyday adventures, since 2014. Built in small batches, designed to last.</p>
