        <div className="footer-bottom">
          <span>© 2026 Northstride Goods Co. — All rights reserved.</span>
          <div className="pay">
            {['VISA','MC','AMEX','PAY','GPAY'].map(p => <div className="pay-card" key={p}>{p}</div>)}
          </div>
        </div>
      </div>
    </footer>
  );
};

// ============ APP ============
const App = () => {
  const [cart, setCart] = useState(2);
  const [wishlist, setWishlist] = useState(new Set([4]));

  const toggleWish = (id) => setWishlist(prev => {
    const next = new Set(prev);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;
  });
  const addToCart = () => setCart(c => c + 1);

  return (
    <>
      <AnnouncementBar/>
      <Nav cartCount={cart} wishCount={wishlist.size}/>
      <Hero/>
      <Marquee/>
      <FeaturedProducts wishlist={wishlist} onWish={toggleWish} onAdd={addToCart}/>
      <Deals/>
      <Categories/>
      <Editorial/>
      <Newsletter/>
      <Footer/>
    </>
  );
};

ReactDOM.createRoot(document.getElementById('root')).render(<App/>);
