const Countdown = () => {
  const target = useMemo(() => Date.now() + (1000 * 60 * 60 * 36) + 1000 * 60 * 27, []);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, target - now);
  const hh = Math.floor(diff / 3600000);
  const mm = Math.floor((diff % 3600000) / 60000);
  const ss = Math.floor((diff % 60000) / 1000);
  const pad = n => String(n).padStart(2, '0');
  return (
    <div className="countdown">
      <div className="cd-block"><strong>{pad(hh)}</strong><span>Hours</span></div>
      <div className="cd-block"><strong>{pad(mm)}</strong><span>Min</span></div>
      <div className="cd-block"><strong>{pad(ss)}</strong><span>Sec</span></div>
    </div>
  );
};

