const App = () => {
  const [cart, setCart] = useState(2);
  const [wishlist, setWishlist] = useState(new Set([4]));

  const toggleWish = (id) => setWishlist(prev => {
    const next = new Set(prev);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;
  });
  const addToCart = () => setCart(c => c + 1);

  return (
    <>
      <AnnouncementBar/>
      <Nav cartCount={cart} wishCount={wishlist.size}/>
      <Hero/>
      <Marquee/>
      <FeaturedProducts wishlist={wishlist} onWish={toggleWish} onAdd={addToCart}/>
      <Deals/>
      <Categories/>
      <Editorial/>
      <Newsletter/>
      <Footer/>
    </>
  );
};

